export type Severity = 'error' | 'warning' | 'info';

export interface Finding {
  severity: Severity;
  /** Stable machine code, e.g. `sql.rls-missing`. Tests and the report key off it. */
  code: string;
  file?: string;
  line?: number;
  /** What is wrong, in plain language. */
  message: string;
  /** What to do about it. */
  fix?: string;
}

/** The compact tables generated by `scripts/wpParity/pluginCheckData.mjs`. */
export interface Names {
  wordpress?: string;
  hooks: string[];
  functions: string[];
  asyncFunctions: string[];
  notApplicable: { hooks: Record<string, number>; functions: Record<string, number> };
  reasons: string[];
  packages: string[];
}

/** Syntax problems of one source file. Supplied by the caller (TypeScript in the browser). */
export type SyntaxChecker = (file: string, source: string) => Array<{ line: number; message: string }>;

export interface CheckOptions {
  names: Names;
  syntax?: SyntaxChecker;
}

export type Verdict = 'pass' | 'warn' | 'fail';

export interface Report {
  plugin: { id?: string; name?: string; version?: string };
  verdict: Verdict;
  findings: Finding[];
  counts: { error: number; warning: number; info: number };
  files: number;
  /** What was and was not examined, in plain language, so a pass is never read as more than it is. */
  scope: string[];
}

/** One file of the archive: text for source files, bytes for everything else. */
export type Entries = Map<string, Uint8Array | string>;
